String fn0(List<String> commands) {
  List<String> stack = [];
  List<String> queue = [];
  for (String cmd in commands) {
    if (cmd.startsWith('PUSH ')) {
      stack.add(cmd.substring(5));
    } else if (cmd.startsWith('ENQUEUE ')) {
      queue.add(cmd.substring(8));
    } else if (cmd == 'POP') {
      if (stack.isNotEmpty) stack.removeLast();
    } else if (cmd == 'DEQUEUE') {
      if (queue.isNotEmpty) queue.removeAt(0);
    } else if (cmd == 'STACK_TO_QUEUE') {
      if (stack.isNotEmpty) {
        queue.add(stack.removeLast());
      }
    } else if (cmd == 'QUEUE_TO_STACK') {
      if (queue.isNotEmpty) {
        stack.add(queue.removeAt(0));
      }
    } else if (cmd == 'CLEAR_STACK') {
      stack.clear();
    } else if (cmd == 'CLEAR_QUEUE') {
      queue.clear();
    }
  }
  return 'Stack: ${stack.toString()}; Queue: ${queue.toString()}';
}

Map<String, dynamic> fn0(int bracketSize) {
  if (bracketSize < 1) {
    return {
      "rounds": 0,
      "totalMatches": 0,
      "firstRoundMatches": 0,
      "byes": 0,
      "bracketSize": bracketSize,
      "isPowerOfTwo": 0
    };
  }

  int nextPow2 = 1;
  while (nextPow2 < bracketSize) {
    nextPow2 <<= 1;
  }

  int rounds = 0;
  int temp = nextPow2;
  while (temp > 1) {
    temp >>= 1;
    rounds++;
  }

  int byes = nextPow2 - bracketSize;
  int totalMatches = bracketSize - 1;
  int firstRoundMatches = (bracketSize - byes) ~/ 2;
  int isPowerOfTwo = (bracketSize == nextPow2) ? 1 : 0;

  return {
    "rounds": rounds,
    "totalMatches": totalMatches,
    "firstRoundMatches": firstRoundMatches,
    "byes": byes,
    "bracketSize": bracketSize,
    "isPowerOfTwo": isPowerOfTwo
  };
}

